function boxBlur(data,w,h,radius){
  var r=Math.max(0,Math.round(radius));
  if(r===0) return data;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sr=0,sg=0,sb=0,sa=0,n=0;
    for(var yy=Math.max(0,y-r);yy<=Math.min(h-1,y+r);yy++) for(var xx=Math.max(0,x-r);xx<=Math.min(w-1,x+r);xx++){
      var i=(yy*w+xx)*4; sr+=data[i]; sg+=data[i+1]; sb+=data[i+2]; sa+=data[i+3]; n++;
    }
    var p=(y*w+x)*4; out[p]=sr/n; out[p+1]=sg/n; out[p+2]=sb/n; out[p+3]=sa/n;
  }
  return out;
}
function wcHash(x,y){ var n=((x*374761393+y*668265263)>>>0); n=((n^(n>>>13))*1274126177)>>>0; n=n^(n>>>16); return (n>>>0)/4294967296; }
function watercolorProcess(data,w,h,opts){
  opts=opts||{};
  var soft=opts.soft!=null?opts.soft:6;
  var sat=opts.sat!=null?opts.sat:0.55;
  var grain=opts.grain!=null?opts.grain:0.06;
  if(soft<0)soft=0; else if(soft>14)soft=14;
  if(sat<0)sat=0; else if(sat>1)sat=1;
  if(grain<0)grain=0; else if(grain>0.3)grain=0.3;
  var base=(soft===0)?data:boxBlur(data,w,h,soft);
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var r=base[p], g=base[p+1], b=base[p+2];
    var L=0.299*r+0.587*g+0.114*b;
    r=L+(r-L)*sat; g=L+(g-L)*sat; b=L+(b-L)*sat;
    var gran=(Math.sin(x*0.07)+Math.sin(y*0.07+1.3))*0.5;
    var fac=1+gran*grain*0.4;
    var hsh=wcHash(x,y);
    var gp=(hsh-0.5)*grain*30;
    out[p]=r*fac+gp; out[p+1]=g*fac+gp; out[p+2]=b*fac+gp; out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={watercolorProcess:watercolorProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WatercolorForgePure = EXPORTS; }
